import { HUNDRED_HAND_MILE as C, HUNDRED_HAND_POS as POS, hundredHandCandidateEnabled } from '../data/hundredHandMile.js';
import { makeShipEntitySpec } from './ships.js';
import { NPC_JOB_PHASE as PHASE } from './npcJobs.js';

export const MILE_CONVOY_RECORD = `${C.siteId}:final-convoy`;
export const MILE_CONVOY_JOB = `job:${MILE_CONVOY_RECORD}`;
export const MILE_CONVOY_ROUTE = Object.freeze([
  Object.freeze({ id: `${C.routeId}:origin`, x: POS.x - 180, z: POS.z - 100 }),
  Object.freeze({ id: `${C.routeId}:arrival`, x: POS.x + 180, z: POS.z - 100 }),
]);
const near = (a, b, r) => !!(a && b && Math.hypot(a.x - b.x, a.z - b.z) <= r);
const fresh = () => ({ version: 1, jobId: null, routeId: C.routeId, outcome: null,
  witnessedByPlayer: false, observedOrigin: false, observedCrossing: false });
const deny = reason => ({ ok: false, reason });

// One bounded producer; npcJobsRuntime owns movement, the native world owns poses/clearance,
// and this saved owner retains the one-shot outcome after the ordinary job is retired.
export const hundredHandMileTraffic = {
  name: 'hundredHandMileTraffic',
  init(ctx) {
    Object.assign(this, { state: ctx.state, registry: ctx.registry, helpers: ctx.helpers, bus: ctx.bus });
    this.newGame(); this._subs = [];
    const on = (event, fn) => this._subs.push(this.bus.on(event, fn));
    on('save:restoring', () => { this._restoring = true; this._hull = null; this._entry = null; this._proof = null; });
    on('save:loaded', () => { this._restoring = false; this.afterContinue(); });
    on('sector:exit', () => { this._hull = null; this._entry = null; this._proof = null; });
    on('entity:destroyed', p => {
      // A recycled numeric id or a forged scalar receipt is not this convoy's death.
      if (!this._restoring && this._hull && p?.entity === this._hull && p.id === this._hull.id) {
        if (p.reason === 'virtualize' && this._jobs()?.acceptHundredHandShelf?.(this, this._hull) === true) { this._hull = null; this._entry = null; this._proof = null; }
        else this._lost();
      }
