  },
  newGame() { this._row = fresh(); this._hull = null; this._entry = null; this._proof = null; this._restoring = false; },
  canRestoreFarActor(npcOwner, row, entry) {
    if (this._restoring || !hundredHandCandidateEnabled(this.state) || npcOwner !== this.registry?.get('npcJobsRuntime')
      || entry !== this._jobs()?.get(MILE_CONVOY_JOB) || row.data?.worldRecordId !== MILE_CONVOY_RECORD) return false;
    return this._row.jobId === MILE_CONVOY_JOB && !this._row.outcome && entry.job?.payload?.routeId === C.routeId
      && entry.job.route?.length === 2 && entry.job.route.every((p, i) => p.id === MILE_CONVOY_ROUTE[i].id
        && p.pos?.x === MILE_CONVOY_ROUTE[i].x && p.pos?.z === MILE_CONVOY_ROUTE[i].z);
  },
  serialize() { return { ...this._row }; },
  deserialize(raw) {
    this._row = fresh(); this._hull = null; this._entry = null; this._proof = null;
    if (raw?.version !== 1 || raw.routeId !== C.routeId || raw.jobId !== MILE_CONVOY_JOB) return;
    this._row.jobId = MILE_CONVOY_JOB;
    this._row.outcome = ['arrived', 'lost'].includes(raw.outcome) ? raw.outcome : null;
    this._row.observedOrigin = raw.observedOrigin === true;
    this._row.observedCrossing = this._row.observedOrigin && raw.observedCrossing === true;
    this._row.witnessedByPlayer = this._row.outcome === 'arrived' && this._row.observedCrossing && raw.witnessedByPlayer === true;
  },
  afterContinue() {
    if (this._row.jobId !== MILE_CONVOY_JOB || this._row.outcome !== 'lost') return;
    // Older valid saves recorded the terminal job loss but left its generic
    // world snapshot alive. Reconcile that exact authored identity after the
    // saved bodies are restored, before flight resumes. This is not a new kill.
    const world = this.registry?.get('world');
    // Capture current authored lives before the ordinary job release clears its claim.
    const originals = [...this.state.entities.values()].filter(e => e.id !== this.state.playerId
      && e.type === 'ship' && e.data?.defId === 'ship_mule' && e.team === 2
      && e.data?.worldRecordId === MILE_CONVOY_RECORD && e.data?.hundredHandMileConvoy === true
      && e.data?.jobId === MILE_CONVOY_JOB
      && (!e.data?.persistenceOwner || e.data.persistenceOwner === 'world'))
      .map(entity => ({ entity, life: entity.occupantGeneration }));
    const entry = this._jobs()?.get?.(MILE_CONVOY_JOB);
    if (entry?.worldRecordId === MILE_CONVOY_RECORD && entry.job?.id === MILE_CONVOY_JOB
      && entry.job.payload?.hundredHandMile === true && entry.job.payload?.routeId === C.routeId
      && entry.job.route?.length === MILE_CONVOY_ROUTE.length
      && entry.job.route.every((p, i) => p.id === MILE_CONVOY_ROUTE[i].id
        && p.pos?.x === MILE_CONVOY_ROUTE[i].x && p.pos?.z === MILE_CONVOY_ROUTE[i].z))
      this._jobs()?.release?.(MILE_CONVOY_JOB);
    const record = this.state.world?.records?.byId?.[MILE_CONVOY_RECORD];
    const custodyTransferred = record?.outcome === 'custody_transferred'
      || [...this.state.entities.values()].some(e => e.data?.worldRecordId === MILE_CONVOY_RECORD
        && (e.data?.persistenceOwner === 'shipjack' || e.data?.shipjackCustody === 'player'
          || (e.data?.vesselId && this.state.player?.ownedShips?.some(s => s.vesselId === e.data.vesselId))));
    if (custodyTransferred) { this._hull = null; this._entry = null; this._proof = null; return; }
    for (const { entity: e, life } of originals) {
      if (this.state.entities.get(e.id) !== e || e.occupantGeneration !== life
        || e.id === this.state.playerId || e.type !== 'ship' || e.data?.defId !== 'ship_mule'
        || e.data?.worldRecordId !== MILE_CONVOY_RECORD || e.data?.hundredHandMileConvoy !== true
        || (e.data?.jobId != null && e.data.jobId !== MILE_CONVOY_JOB) || e.team !== 2
        || (e.data?.persistenceOwner && e.data.persistenceOwner !== 'world')) continue;
      if (!this.state.world?.records?.byId?.[MILE_CONVOY_RECORD]) world?.upsertWorldRecord?.(e);
      this.helpers?.removeEntity?.(e.id, { immediate: true, reason: 'mile-lost-restore' });
    }
    const currentRecord = this.state.world?.records?.byId?.[MILE_CONVOY_RECORD];
    if (currentRecord && currentRecord.alive !== false)
      world?.markWorldRecordDestroyed?.(MILE_CONVOY_RECORD, { outcome: 'destroyed' });
