  },
  dispose() { for (const off of this._subs || []) off?.(); this._subs = []; },
  _world() { return this.registry?.get('hundredHandMileWorld'); },
  _jobs() { return this.helpers?.npcJobs; },
  _enabled() { return !this._restoring && hundredHandCandidateEnabled(this.state); },
  ports() { return { proveRoute: () => this.proveRoute(), dispatchConvoy: p => this.dispatchConvoy(p), readConvoy: id => this.readConvoy(id) }; },
  proveRoute() {
    this._proof = null;
    if (!this._enabled() || this.state.world?.currentSectorId !== C.sectorId) return deny('route-unavailable');
    const proof = this._world()?.proveRoute?.();
    if (!proof?.ok || proof.routeId !== C.routeId || proof.tick !== this.state.tick) return deny('native-clearance-required');
    this._proof = proof; return proof;
  },
  dispatchConvoy(proof) {
    if (!this._enabled()) return deny('candidate-disabled');
    if (this._row.jobId) return { ok: true, jobId: this._row.jobId, duplicate: true };
    if (proof !== this._proof || !proof?.ok || proof.tick !== this.state.tick || proof.routeId !== C.routeId) return deny('fresh-owner-proof-required');
    const recheck = this._world()?.proveRoute?.();
    if (!recheck?.ok || recheck.tick !== this.state.tick || recheck.routeId !== C.routeId) return deny('native-route-changed');
