    if (!budget?.request || !budget.bindEntity || !budget.release || !jobs?.assign || !jobs.get
      || !this.helpers?.spawnEntity || !this.helpers?.removeEntity) return deny('budgeted-owner-unavailable');
    if (jobs.get(MILE_CONVOY_JOB) || this.state.world?.records?.byId?.[MILE_CONVOY_RECORD]
      || [...this.state.entities.values()].some(e => e.data?.worldRecordId === MILE_CONVOY_RECORD)) return deny('convoy-identity-already-owned');
    if (budget.request(1, MILE_CONVOY_RECORD) !== 1) return deny('spawn-budget-full');
    const spec = makeShipEntitySpec('ship_mule', { team: 2, factionId: 'faction_free', pos: { ...MILE_CONVOY_ROUTE[0] },
      ai: { archetype: 'fleeing_trader', passive: true, spawnContext: 'convoy_civilian' } });
    spec.data = { ...spec.data, worldRecordId: MILE_CONVOY_RECORD, identityKey: MILE_CONVOY_RECORD,
      sectorId: C.sectorId, durable: true, hundredHandMileConvoy: true, trafficLabel: 'Hundred-Hand Mile convoy' };
    spec.flags = { ...spec.flags, persistent: true };
    const hull = this.helpers.spawnEntity(spec);
    if (!hull) { budget.release(MILE_CONVOY_RECORD); return deny('spawn-refused'); }
    if (budget.bindEntity(hull.id, MILE_CONVOY_RECORD) !== true) {
      this.helpers.removeEntity(hull.id, { immediate: true, reason: 'mile-budget-refused' }); budget.release(MILE_CONVOY_RECORD);
      return deny('budget-binding-refused');
    }
    const jobId = jobs.assign(hull, { kind: 'hauler', sectorId: C.sectorId, route: MILE_CONVOY_ROUTE.map(p => ({ id: p.id, pos: { x: p.x, z: p.z } })),
      speed: 26, loadS: 1, approachS: 1, unloadS: 1, payload: { hundredHandMile: true, routeId: C.routeId } });
    if (jobId !== MILE_CONVOY_JOB) {
      if (jobId) jobs.release?.(jobId);
      this.helpers.removeEntity(hull.id, { immediate: true, reason: 'mile-job-refused' }); budget.release(MILE_CONVOY_RECORD);
      return deny('job-assignment-refused');
    }
