    return { ok: true, jobId };
  },
  _bind(entry, hull) {
    if (this._row.jobId !== MILE_CONVOY_JOB || !entry || entry !== this._jobs()?.get(MILE_CONVOY_JOB) || entry.worldRecordId !== MILE_CONVOY_RECORD
      || entry.job?.id !== MILE_CONVOY_JOB || entry.job?.payload?.routeId !== C.routeId
      || !hull || hull.alive === false || this.state.entities.get(hull.id) !== hull
      || hull.data?.worldRecordId !== MILE_CONVOY_RECORD || hull.data?.jobId !== MILE_CONVOY_JOB || entry.entityId !== hull.id) return false;
    if ((this._hull && this._hull !== hull) || (this._entry && this._entry !== entry)) return false;
    let count = 0;
    for (const e of this.state.entities.values()) if (e.alive !== false && e.data?.worldRecordId === MILE_CONVOY_RECORD) count++;
    if (count !== 1) return false;
    if (entry.job.route?.length !== 2 || !entry.job.route.every((p, i) => p.id === MILE_CONVOY_ROUTE[i].id
      && p.pos?.x === MILE_CONVOY_ROUTE[i].x && p.pos?.z === MILE_CONVOY_ROUTE[i].z)) return false;
    this._hull = hull; this._entry = entry; return true;
  },
  jobTarget(entry, hull) {
    if (!this._enabled() || !this._bind(entry, hull) || !this._world()?.nativePosition?.(hull)) return null;
    const destination = [PHASE.TRANSIT, PHASE.APPROACH, PHASE.UNLOAD].includes(entry.job.phase);
    // The midpoint is an existing physical crossing gate, not a timer receipt.
    // Aim through it before the far endpoint: lateral drift can otherwise carry
    // a real hull around the gate and strand an arrived job forever.
    if (destination && !this._row.observedCrossing)
      return { pos: { x: POS.x, z: POS.z - 100 }, reach: 12, vel: { x: 0, z: 0 } };
    return { pos: MILE_CONVOY_ROUTE[destination ? 1 : 0], reach: 12, vel: { x: 0, z: 0 } };
  },
  canAdvanceJob(entry, hull) {
    if (!this._enabled() || this._row.outcome || !this._bind(entry, hull)) return false;
    const pos = this._world()?.nativePosition?.(hull);
    if (!pos) return false;
    if (near(pos, MILE_CONVOY_ROUTE[0], 20)) this._row.observedOrigin = true;
    if (this._row.observedOrigin && Math.abs(pos.x - POS.x) <= 35 && Math.abs(pos.z - (POS.z - 100)) <= 20)
      this._row.observedCrossing = true;
    if ([PHASE.APPROACH, PHASE.UNLOAD].includes(entry.job.phase))
      return this._row.observedCrossing && near(pos, MILE_CONVOY_ROUTE[1], 20);
    return true;
  },
  finishJob(entry, hull) {
    if (!this._enabled() || this._row.outcome || !this._bind(entry, hull) || entry.job.phase !== PHASE.COMPLETE
      || !this._row.observedCrossing || !near(this._world()?.nativePosition?.(hull), MILE_CONVOY_ROUTE[1], 20)) return false;
    const player = this.state.entities.get(this.state.playerId), playerPos = this._world()?.nativePosition?.(player);
    this._row.outcome = 'arrived';
    this._row.witnessedByPlayer = player?.alive !== false && this.state.world?.currentSectorId === C.sectorId
      && near(playerPos, POS, C.scanRange) && near(playerPos, this._world()?.nativePosition?.(hull), C.scanRange);
    return true;
  },
  ownsDestruction(entry, receipt) {
    return entry === this._entry && receipt?.entity === this._hull && receipt?.id === this._hull?.id;
  },
  _lost() {
    if (!hundredHandCandidateEnabled(this.state)) return;
    if (this._row.jobId && !this._row.outcome) {
      this._row.outcome = 'lost';
      // A genuine lifetime loss need not have passed through combat's killed
      // event. The ordinary job already owns a durable world record; retire it
      // through that owner too, or Continue can resurrect its last live snapshot.
      // Shelving and save reconstruction never enter this terminal path.
      this.registry?.get('world')?.markWorldRecordDestroyed?.(MILE_CONVOY_RECORD, { outcome: 'destroyed' });
      if (this._hull) this.helpers?.spawnBudget?.releaseEntity?.(this._hull.id, this._hull);
    }
  },
  readConvoy(id) { return id === this._row.jobId && id ? { ...this._row } : null; },
  update() {
    if (!this._enabled() || !this._row.jobId || this._row.outcome) return;
    const entry = this._jobs()?.get(this._row.jobId);
    if (!entry) { this._lost(); return; }
    if (entry.entityId == null) { this._hull = null; this._entry = null; return; } // world-owned demotion, never respawn
    const hull = this.state.entities.get(entry.entityId);
    if (!hull || hull.alive === false || (this._hull && this._hull !== hull)) { this._lost(); return; }
    this.canAdvanceJob(entry, hull);
  },
};

