import { HUNDRED_HAND_MILE as C, HUNDRED_HAND_POS as POS,
  hundredHandCandidateEnabled, hundredHandContributionId, validHundredHandContribution } from '../data/hundredHandMile.js';
import { makeShipEntitySpec } from './ships.js';
import { getCombatKernel } from '../combat/kernel.js';

// One repair, one conserved original and one budgeted working hull. Sim time authorizes
// dispatch only; the native tow/cargo/graph owners still determine physical completion.
export const MILE_CREW_REPAIR = Object.freeze({ moduleId: 'power', delaySeconds: 180, exclusionRadius: 700 });
export const MILE_CREW_RECORD = `${C.siteId}:repair-crew`;
export const MILE_CREW_JOB = `job:${MILE_CREW_RECORD}`;
export const MILE_CREW_LEASE = `${C.siteId}:repair-tow`;
const receiptId = hundredHandContributionId('power');
const failures = new Set(['timeout', 'target_lost', 'hull_lost', 'lease_released', 'custody-changed', 'source-upset']);
const fresh = () => ({ version: 1, siteId: C.siteId, startedAt: null, contributionId: null, spawned: false, lost: false, failure: null, plan: null });
const deny = reason => ({ ok: false, reason });
const sameReceipt = (a, b) => ['id', 'siteId', 'moduleId', 'generation', 'sourceId', 'fingerprint', 'at', 'qty', 'by', 'commodityId']
  .every(key => a?.[key] === b?.[key]);
const point = p => p && Number.isFinite(p.x) && Number.isFinite(p.z) && Math.hypot(p.x - POS.x, p.z - POS.z) < 2000;
function savedPlan(p) {
  if (!p || !point(p.spawnPos) || !point(p.holdPos) || !point(p.destPos)
    || !Number.isFinite(p.axis?.x) || !Number.isFinite(p.axis?.z) || Math.abs(Math.hypot(p.axis.x, p.axis.z) - 1) > .001
    || !Array.isArray(p.waypoints) || p.waypoints.length > 8 || !p.waypoints.every(point)) return null;
  return { spawnPos: { ...p.spawnPos }, holdPos: { ...p.holdPos }, destPos: { ...p.destPos }, axis: { ...p.axis },
    waypoints: p.waypoints.map(p => ({ ...p })), aimAngle: Math.atan2(-p.axis.z, -p.axis.x) };
}

export const hundredHandMileCrew = {
  name: 'hundredHandMileCrew',
  init(ctx) {
    this.ctx = ctx; this.state = ctx.state; this.registry = ctx.registry; this.helpers = ctx.helpers;
    this._row = fresh(); this._restoring = false; this._settling = false; this._reason = null;
    this._hull = null; this._hullLife = null; this._plan = null;
    this._subs = [ctx.bus.on('save:restoring', () => { this._restoring = true; this._hull = null; this._hullLife = null; this._plan = null; }),
      ctx.bus.on('save:loaded', () => this.afterContinue()),
      ctx.bus.on('entity:destroyed', p => { if (!this._restoring && this._hull && p?.entity === this._hull && p.id === this._hull.id) {
        if (p.reason === 'virtualize' && this._jobs()?.acceptHundredHandShelf?.(this, this._hull) === true) { this._hull = null; this._hullLife = null; }
        else this._lost();
      } }),
      ctx.bus.on('entity:killed', p => { if (!this._restoring && this._hull?.alive === false && (p?.targetId ?? p?.entityId) === this._hull.id) this._lost(); })];
  },
  canRestoreFarActor(npcOwner, row, entry) {
    if (this._restoring || !hundredHandCandidateEnabled(this.state) || npcOwner !== this.registry?.get('npcJobsRuntime')
      || entry !== this._jobs()?.get(MILE_CREW_JOB) || row.data?.worldRecordId !== MILE_CREW_RECORD) return false;
    return this._row.spawned === true && !this._row.lost && !this._row.failure && !this._row.contributionId;
  },
  serialize() { return structuredClone(this._row); },
  deserialize(raw) {
    this._row = fresh(); this._reason = null; this._hull = null; this._hullLife = null; this._plan = null;
    if (raw?.version !== 1 || raw.siteId !== C.siteId) return;
    if (Number.isFinite(raw.startedAt) && raw.startedAt >= 0 && raw.startedAt <= this.state.simTime) this._row.startedAt = raw.startedAt;
    // Saved ids/plans are recovery hints, never renewed resource or native clearance proof.
    if (raw.contributionId === receiptId) this._row.contributionId = receiptId;
    this._row.spawned = raw.spawned === true; this._row.lost = raw.lost === true;
    this._row.failure = failures.has(raw.failure) ? raw.failure : null;
    this._row.plan = savedPlan(raw.plan);
  },
  afterContinue() { this._restoring = false; this._hull = null; this._hullLife = null; this._plan = null; },
  newGame() { this._finish('new-game'); this._row = fresh(); this._reason = null; this._restoring = false; this._hull = null; this._hullLife = null; this._plan = null; },
  dispose() { this._finish('disposed'); for (const off of this._subs || []) off?.(); this._subs = []; },
  readout() { return { ...structuredClone(this._row), ...MILE_CREW_REPAIR, reason: this._reason,
    readyAt: this._row.startedAt == null ? null : this._row.startedAt + MILE_CREW_REPAIR.delaySeconds }; },
  _jobs() { return this.helpers?.npcJobs; },
  _world() { return this.registry?.get('hundredHandMileWorld'); },
  _offscreen() {
    const player = this.state.entities?.get(this.state.playerId);
    return !!(player?.alive !== false && Number.isFinite(player?.pos?.x) && Number.isFinite(player?.pos?.z)
      && Math.hypot(player.pos.x - POS.x, player.pos.z - POS.z) > MILE_CREW_REPAIR.exclusionRadius);
  },
  currentHull() {
    if (this._row.lost || !this._row.spawned) return null;
    const hulls = [...this.state.entities.values()].filter(e => e.alive !== false && e.data?.worldRecordId === MILE_CREW_RECORD);
    if (hulls.length !== 1) return null;
    const hull = hulls[0], entry = this._jobs()?.get?.(MILE_CREW_JOB);
    if ((this._hull && (this._hull !== hull || this._hullLife !== hull.occupantGeneration)) || !Number.isSafeInteger(hull.occupantGeneration) || hull.occupantGeneration < 1
      || hull.data?.hundredHandMileCrew !== true || hull.data?.jobId !== MILE_CREW_JOB
      || entry?.entityId !== hull.id || entry.worldRecordId !== MILE_CREW_RECORD
      || entry.job?.payload?.hundredHandMileCrew !== true) return null;
    this._hull = hull; this._hullLife = hull.occupantGeneration; return hull;
  },
  isCurrentTow(hull, target) {
    if (this._restoring || this._row.lost || this._row.failure || !hundredHandCandidateEnabled(this.state) || hull !== this.currentHull()
      || !hull || target?.alive === false || this.state.entities.get(target?.id) !== target
      || target?.data?.worldRecordId !== `${C.siteId}:power-original` || target.data.hundredHandGeneration !== 0
      || target.data.hundredHandInstalled || this._world()?._find?.('power') !== target) return false;
    const row = this.registry.get(C.owner)?.readout?.();
    if (!row?.accepted || row.abandoned || row.destroyedModuleIds?.includes('power') || row.installedModuleIds?.includes('power')
      || (row.pendingInstall && row.pendingInstall.receiptId !== receiptId)
      || row.contributions?.some(r => r.moduleId === 'power' && r.by !== 'crew')) return false;
    const lines = getCombatKernel(this.ctx).attachments.listForEntity(target.id);
    return !lines.some(line => line.state === 'active' && (line.ownerId !== hull.id || line.ownerGeneration !== hull.occupantGeneration));
  },
  currentTarget() { return this._world()?._find?.('power') || null; },
  constructionSettled(hull, target) {
    const receipt = this._canonicalCrewReceipt(this.registry.get(C.owner), this.registry.get('cargo'));
    return !!(receipt && hull && hull === this.currentHull() && target && target === this.currentTarget()
      && target.data?.hundredHandInstalled === true && target.data.hundredHandReceiptId === receipt.id
      && target.data.hundredHandGeneration === 0 && this._world()?._row?.parts?.power?.installedReceiptId === receipt.id);
  },
  towPlan(hull, target) { return this.isCurrentTow(hull, target) && this._plan?.target === target ? this._plan : null; },
  _canonicalCrewReceipt(graph, cargo) {
    const receipt = cargo?.canonicalHundredHandContribution?.(receiptId), accepted = graph?.contributionReceipt?.(receiptId);
    return validHundredHandContribution(receipt) && receipt.by === 'crew' && receipt.id === receiptId && sameReceipt(receipt, accepted) ? receipt : null;
  },
  _finish(reason) {
    if (!hundredHandCandidateEnabled(this.state)) return;
    this.registry?.get('npcJobsRuntime')?.finishHundredHandTow?.(this, MILE_CREW_JOB, reason);
    if (this._jobs()?.controlClaim?.(MILE_CREW_JOB)?.claimId === MILE_CREW_LEASE) this._jobs().releaseControl(MILE_CREW_JOB, MILE_CREW_LEASE);
  },
  towFailed(npcOwner, reason) {
    if (!hundredHandCandidateEnabled(this.state) || !npcOwner || npcOwner !== this.registry?.get('npcJobsRuntime') || !this._row.spawned || !failures.has(reason)) return false;
    this._row.failure = reason; this._reason = `crew-tow-${reason}`; return true;
  },
  _lost() { if (!hundredHandCandidateEnabled(this.state)) return; this._row.lost = true; this._reason = 'crew-hull-lost'; this._finish('hull-lost'); this._hull = null; },
  _startOrResume() {
    const world = this._world(), jobs = this._jobs(), budget = this.helpers?.spawnBudget;
    if (typeof world?.crewTransferPlan !== 'function' || typeof world.crewSpawnClear !== 'function'
      || !jobs?.assign || !jobs.get || !jobs.requestTowAssist || !jobs.claimControl || !budget?.request || !budget.bindEntity || !budget.release)
      return deny('crew-transfer-owner-unavailable');
    if (!this._plan) {
      const plan = world.crewTransferPlan(this, this._row.plan);
      if (!plan?.ok || !plan.target || !savedPlan(plan)) return plan?.ok ? deny('crew-plan-invalid') : plan || deny('crew-native-plan-unavailable');
      this._plan = plan; this._row.plan = savedPlan(plan);
    }
