    if (!hull) {
      if (this._row.spawned) return deny('crew-native-hull-pending');
      if (jobs.get(MILE_CREW_JOB) || this.state.world?.records?.byId?.[MILE_CREW_RECORD]
        || [...this.state.entities.values()].some(e => e.data?.worldRecordId === MILE_CREW_RECORD)) return deny('crew-identity-already-owned');
      const spec = makeShipEntitySpec('ship_mule', { team: 2, factionId: 'faction_free', pos: { ...this._plan.spawnPos },
        ai: { archetype: 'fleeing_trader', passive: true, spawnContext: 'industrial_crew' } });
      spec.rot = this._row.plan.aimAngle;
      spec.data = { ...spec.data, worldRecordId: MILE_CREW_RECORD, identityKey: MILE_CREW_RECORD, sectorId: C.sectorId,
        durable: true, hundredHandMileCrew: true, trafficLabel: 'Hundred-Hand repair crew' };
      spec.flags = { ...spec.flags, persistent: true };
      const clear = world.crewSpawnClear(this, spec);
      if (!clear?.ok || clear.tick !== this.state.tick) return clear || deny('crew-spawn-clearance-required');
      if (budget.request(1, MILE_CREW_RECORD) !== 1) return deny('spawn-budget-full');
      hull = this.helpers.spawnEntity?.(spec);
      if (!hull) { budget.release(MILE_CREW_RECORD); return deny('crew-spawn-refused'); }
      if (budget.bindEntity(hull.id, MILE_CREW_RECORD) !== true) {
        this.helpers.removeEntity?.(hull.id, { immediate: true, reason: 'mile-crew-budget-refused' }); budget.release(MILE_CREW_RECORD); return deny('crew-budget-binding-refused');
      }
      const jobId = jobs.assign(hull, { kind: 'hauler', sectorId: C.sectorId, speed: 12, loadS: 1,
        route: [{ id: `${MILE_CREW_RECORD}:hold`, pos: { ...this._plan.holdPos } },
          { id: `${MILE_CREW_RECORD}:depart`, pos: { x: this._plan.holdPos.x + 250, z: this._plan.holdPos.z + 250 } }],
        payload: { hundredHandMileCrew: true, physicalTransfer: true, cargoWorldRecordId: `${C.siteId}:power-original` } });
      if (jobId !== MILE_CREW_JOB) {
        if (jobId) jobs.release?.(jobId); this.helpers.removeEntity?.(hull.id, { immediate: true, reason: 'mile-crew-job-refused' });
        budget.release(MILE_CREW_RECORD); return deny('crew-job-assignment-refused');
