      this._finish('player-or-existing-custody'); this._row.startedAt = null; this._reason = 'player-or-existing-custody'; return;
    }
    if (!this._row.spawned) {
      if (!this._offscreen()) { this._row.startedAt = null; this._reason = 'player-near-site'; return; }
      if (this._row.startedAt == null || this._row.startedAt > this.state.simTime) this._row.startedAt = this.state.simTime;
      if (this.state.simTime - this._row.startedAt < MILE_CREW_REPAIR.delaySeconds) { this._reason = 'authored-delay'; return; }
