import { configureHundredHandMilePorts } from './hundredHandMile.js';
import { HUNDRED_HAND_MILE as C } from '../data/hundredHandMile.js';

const RECEIVER_REASONS = new Set([
  'source-outside-receiver', 'receiver-speed-too-high', 'current-native-player-tow-required',
  'hold-outside-service-receiver', 'unreserved-cargo-required',
  'installation-volume-occupied-or-unknown', 'installation-volume-occupied',
  'finite-original-source-unavailable', 'original-source-depleted', 'stale-revision',
]);

// Binds real owners after their initialization. No copied receipt or fallback transaction owner.
export const hundredHandMileIntegration = {
  name: 'hundredHandMileIntegration',
  init(ctx) {
    this.state=ctx.state; this.registry=ctx.registry; this.bus=ctx.bus;
    this.bind();
    this._subs=[ctx.bus.on('scan:completed', p=>this.inspect(p?.targetId ?? p?.entityId)),
      ctx.bus.on('scan:pulse', p=>{
        const player=this.state.entities?.get(this.state.playerId);
        if (player && p?.pos && Math.hypot(player.pos.x-p.pos.x,player.pos.z-p.pos.z)<1) this.inspect(this.state.player?.targetId);
      }),ctx.bus.on('hundredHandMile:command', p=>this.command(p))];
  },
  bind() {
    const world=this.registry.get('hundredHandMileWorld'), traffic=this.registry.get('hundredHandMileTraffic');
    configureHundredHandMilePorts(this.state, world?.ports && traffic?.ports ? {...world.ports(),...traffic.ports()} : null);
  },
  offerReadout(graph) {
    const row = graph.readout(), tick = this.state.tick;
    if (!row.enabled || !row.accepted || row.abandoned || row.pendingInstall
      || !row.completedMilestoneIds.includes('survey')) return row;
    const modules = {};
    if (Number.isSafeInteger(row.revision) && Number.isSafeInteger(tick)) {
      for (const [moduleId, chapterId] of [['power', 'recover_power'], ['guide', 'restore_guide'], ['cargo', 'deliver_cargo']]) {
        if (row.installedModuleIds.includes(moduleId)) continue;
        // Prepare is advisory: never retain its body, receipt, fingerprint or clearance proof.
        const quote = graph.prepareContribution?.(chapterId, row.revision);
        modules[moduleId] = quote?.ok === true && quote.revision === row.revision
          && Number.isSafeInteger(quote.nativeTick) && quote.nativeTick >= 0
          ? { ok: true, nativeTick: quote.nativeTick }
          : { ok: false, reason: RECEIVER_REASONS.has(quote?.reason) ? quote.reason : 'receiver-check-unavailable' };
      }
    }
    return { ...row, receiverChecks: { revision: row.revision, tick, modules } };
  },
  inspect(targetId) {
    const target=this.state.entities?.get(targetId), world=this.registry.get('hundredHandMileWorld');
    if (!target || target.alive===false || target.data?.persistenceOwner!=='hundredHandMileWorld' || !world?.inspectSite?.().ok) return false;
    this.bus.emit('hundredHandMile:offer',this.offerReadout(this.registry.get(C.owner)));return true;
  },
  command(p) {
    const graph=this.registry.get(C.owner);if(!graph)return;
    let result;
    if(p?.action==='accept')result=graph.accept(p.revision);
    else if(p?.action==='survey')result=graph.survey();
    else if(p?.action==='contribute')result=graph.contribute(p.chapterId,p.revision);
    else if(p?.action==='dispatch')result=graph.dispatch();
    else if(p?.action==='abandon')result=graph.abandon();
    else return;
    this.bus.emit('hundredHandMile:offer',{...this.offerReadout(graph),lastResult:result});
  },
  newGame(){this.bind();},
  dispose(){for(const off of this._subs||[])off?.();configureHundredHandMilePorts(this.state,null);},
};

