import { HUNDRED_HAND_MILE as C, HUNDRED_HAND_POS as POS } from '../data/hundredHandMile.js';

const PREFIX = `${C.siteId}:dialogue:`;
const TTL = 6;
const LINES = Object.freeze({
  offer: 'Mara: We do not need a hero. We need a working power unit.',
  crew_repair: 'Odo: The repair crew brought the power back. That work is on their record.',
  partial: 'Odo: Half a route is not a route. But it is a start we can use.',
  ilex_branch: 'Ilex: There is still room for what survived.',
  first_convoy: 'Kit: Look at that. Ordinary traffic. Practically a miracle.',
  final: 'Mara: Your part is on the record. So is everyone else’s.',
});

// Read-only presentation adapter. The graph alone owns saved dialogue receipts; the
// existing voice arbiter alone owns the floor. Run before its update to retract stale cues.
export const hundredHandMileNarrative = {
  name: 'hundredHandMileNarrative',
  init(ctx) {
    this.dispose();
    this.state = ctx.state; this.registry = ctx.registry; this.bus = ctx.bus; this.helpers = ctx.helpers;
    this._pending = null; this._restoring = false;
    this._subs = [
      this.bus.on('voice:surface', p => this._surfaced(p)),
      this.bus.on('voice:clear', p => {
        if (this._pending?.heard && p?.id === PREFIX + this._pending.id) this._pending.cleared = true;
      }),
      this.bus.on('save:restoring', () => { this._restoring = true; this._clear(); }),
      this.bus.on('save:loaded', () => { this._restoring = false; this._clear(); }),
      ...['sector:exit', 'dock:completed'].map(event => this.bus.on(event, () => this._clear())),
    ];
  },
  _context() {
    if (this._restoring) return null;
    const player = this.state.entities?.get(this.state.playerId);
    if (!player || player.alive === false || this.state.world?.currentSectorId !== C.sectorId
      || Math.hypot(player.pos.x - POS.x, player.pos.z - POS.z) > C.scanRange) return null;
    const graph = this.registry.get(C.owner), row = graph?.readout?.();
    if (!row?.enabled || row.abandoned) return null;
    // A visited location or copied mission payload is not a live target. The native
    // world's current site inspection also disappears when the mile is destroyed.
    const proof = this.registry.get('hundredHandMileWorld')?.inspectSite?.();
    if (!proof?.ok || proof.siteId !== C.siteId || proof.tick !== this.state.tick) return null;
    return { graph, row };
  },
  _eligible(id, { graph, row }) {
    const milestone = chapter => !!graph.prepareMilestone?.(chapter);
    const installed = module => row.installedModuleIds.includes(module)
      && row.completedMilestoneIds.includes({ power: 'recover_power', guide: 'restore_guide', cargo: 'deliver_cargo' }[module])
      && row.contributions.some(r => r.moduleId === module && !row.destroyedContributionIds.includes(r.id) && graph.contributionReceipt?.(r.id));
    if (id === 'offer') return row.canAccept && !row.accepted;
    if (!row.accepted) return false;
    if (id === 'crew_repair') return installed('power') && row.contributions.some(r => r.moduleId === 'power' && r.by === 'crew' && graph.contributionReceipt?.(r.id));
    if (id === 'partial') return row.branch === 'PARTIAL' && !row.finalConvoyOutcome
      && !row.finalConvoyJobId && row.installedModuleIds.length < 3 && (installed('power') || installed('guide'));
    if (id === 'ilex_branch') return row.evidence.cargoVariant === 'seed'
      && row.evidence.survivingVaults > 0 && installed('cargo')
      && row.contributions.some(r => r.moduleId === 'cargo' && r.commodityId === 'cmdty_food'
        && r.qty === 4 && graph.contributionReceipt?.(r.id));
    if (id === 'first_convoy' || id === 'final') return row.finalConvoyOutcome === 'arrived'
      && row.destroyedModuleIds.length === 0 && installed('power') && milestone('witness_convoy')
      && (id !== 'final' || row.dialogueIds.includes('first_convoy'));
    return false;
  },
  _clear() {
    if (this._pending) this.helpers?.voice?.cancel?.(PREFIX + this._pending.id);
    this._pending = null;
  },
  _surfaced(payload) {
    const pending = this._pending;
    if (!pending || pending.heard || payload?.id !== PREFIX + pending.id || payload.text !== LINES[pending.id]) return;
    const context = this._context();
    if (!context || !this._eligible(pending.id, context)) { this._clear(); return; }
    // Enqueue is not delivery: tutorial/danger may deny the floor or expire the cue.
    context.graph.recordDialogue(this, pending.id);
    pending.heard = true;
    pending.until = this.state.simTime + TTL;
  },
  update() {
    const context = this._context();
    if (!context || !this.helpers?.voice?.say || !this.helpers.voice.cancel) { this._clear(); return; }
    if (this._pending) {
      if (this._pending.cleared || !this._eligible(this._pending.id, context) || this.state.simTime >= this._pending.until) this._clear();
      else return;
    }
    const id = Object.keys(LINES).find(key => !context.row.dialogueIds.includes(key) && this._eligible(key, context));
    if (!id) return;
    this._pending = { id, heard: false, until: this.state.simTime + TTL };
    if (!this.helpers.voice.say({ id: PREFIX + id, text: LINES[id], channel: 'comms', ttl: TTL })) this._pending = null;
  },
  newGame() { this._clear(); this._restoring = false; },
  afterContinue() { this.newGame(); },
  dispose() { this._clear(); for (const off of this._subs || []) off?.(); this._subs = []; },
};

