  const text=MILESTONES[r?.chapterId];if(text)this.bus.emit('toast',{text:'Hundred-Hand Mile: '+text,kind:'info',ttl:6});
 })];
  for(const event of ['sector:exit','dock:completed','save:restoring'])this._subs.push(ctx.bus.on(event,()=>this.newGame()));},
