// Presentation only. These are observations from a scan, never installation authority.
export const MILE_RECEIVER_GUIDANCE = Object.freeze({
  'source-outside-receiver': 'The whole part must fit inside its matching receiver. Use short thrust corrections, then brake your ship before the part crosses the socket.',
  'receiver-speed-too-high': 'The part is moving or spinning too fast. For a swinging load, reposition so the line can pull against its motion. Use short forward thrust, then brake and scan again.',
  'current-native-player-tow-required': 'Keep your live Massline attached to the original part. Attach it again if the line was lost.',
  'hold-outside-service-receiver': 'Bring your ship close to the service socket, brake and let it stop rotating.',
  'unreserved-cargo-required': 'Free the required goods in your hold; reserved cargo cannot be contributed.',
  'installation-volume-occupied-or-unknown': 'Clear ships and loose objects from the final socket, then scan again for a clearance check.',
  'installation-volume-occupied': 'Move ships and loose objects clear of the final installation socket.',
  'finite-original-source-unavailable': 'The original part is unavailable. No duplicate can be supplied.',
  'original-source-depleted': 'The original part has no recoverable material left.',
  'stale-revision': 'The work order changed. Scan the site again before contributing.',
});
const unavailable = 'Receiver check unavailable. Scan the site again; installation still needs a current physical check.';
export function mileReceiverFeedback(row, moduleId, currentTick) {
  const snapshot = row?.receiverChecks, result = snapshot?.modules?.[moduleId];
  if (!snapshot || !Number.isSafeInteger(snapshot.revision) || !Number.isSafeInteger(row?.revision)
    || !Number.isSafeInteger(snapshot.tick) || snapshot.tick < 0 || !Number.isSafeInteger(currentTick) || currentTick < 0 || !result) return unavailable;
  if (snapshot.revision !== row.revision || snapshot.tick !== currentTick) return 'Receiver check is out of date. Scan again; installation rechecks the contribution requirements and socket.';
  if (result.ok === true && Number.isSafeInteger(result.nativeTick) && result.nativeTick >= 0)
    return 'Ready at last check. Installation rechecks the current contribution requirements and socket before taking the contribution.';
  return MILE_RECEIVER_GUIDANCE[result.reason] || unavailable;
}

