import { isHundredHandMileEntity, hundredHandMileSource, hundredHandMilePlaceTransform } from '../world/hundredHandMileGeometry.js';
import { cloneMaterialPreservingShaderHooks } from './materialClone.js';

const CURRENT_SECONDS = 3, LAMP_COUNT = 8;
const SHADER_KEY = 'hundred-hand-first-current-v1';
const smooth = value => { const t = Math.max(0, Math.min(1, value)); return t * t * (3 - 2 * t); };
// CPU twin of the small authored-lens shader. No clock or outcome is render-owned.
export function hundredHandLampLevel(index, elapsed, reduced = false) {
  return smooth(reduced ? elapsed / CURRENT_SECONDS : elapsed * LAMP_COUNT / CURRENT_SECONDS - index);
}

function installLensShader(material, geometry, uniforms) {
  const previous = material.onBeforeCompile;
  const previousKey = material.customProgramCacheKey();
  if (!geometry.boundingBox) geometry.computeBoundingBox();
  const { min, max } = geometry.boundingBox;
  if (!(max.x > min.x)) throw new Error('Hundred-Hand lamp batch has no connection-order span');
  const bounds = { value: [min.x, 1 / (max.x - min.x)] };
  material.onBeforeCompile = function (shader, renderer) {
    previous?.call(this, shader, renderer);
    for (const [stage, token] of [['vertexShader', '#include <common>'], ['vertexShader', '#include <begin_vertex>'],
      ['fragmentShader', '#include <common>'], ['fragmentShader', '#include <color_fragment>']]) {
      if (!shader[stage].includes(token)) throw new Error(`Hundred-Hand lens shader contract changed: ${token}`);
    }
    shader.uniforms.sfMileLampBounds = bounds;
    shader.uniforms.sfMileCurrentElapsed = uniforms.elapsed;
    shader.uniforms.sfMileCurrentReduced = uniforms.reduced;
    shader.vertexShader = shader.vertexShader.replace('#include <common>',
      '#include <common>\nuniform vec2 sfMileLampBounds;\nvarying float vSfMileLampIndex;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\n'
        + 'vSfMileLampIndex = floor(clamp((position.x - sfMileLampBounds.x) * sfMileLampBounds.y, 0.0, 1.0) * 7.0 + 0.5);');
    shader.fragmentShader = shader.fragmentShader.replace('#include <common>', '#include <common>\n'
      + 'varying float vSfMileLampIndex;\nuniform float sfMileCurrentElapsed;\nuniform float sfMileCurrentReduced;')
      .replace('#include <color_fragment>', '#include <color_fragment>\n'
        + 'float sfMileCurrent = mix(smoothstep(vSfMileLampIndex, vSfMileLampIndex + 1.0, sfMileCurrentElapsed * 8.0 / 3.0), smoothstep(0.0, 3.0, sfMileCurrentElapsed), sfMileCurrentReduced);\n'
        + 'diffuseColor.rgb *= sfMileCurrent;');
