      const token = '#include <emissivemap_fragment>';
      if (!shader.fragmentShader.includes(token)) throw new Error('Hundred-Hand lens shader contract changed: emissivemap_fragment');
      shader.fragmentShader = shader.fragmentShader.replace(token, token + '\ntotalEmissiveRadiance *= sfMileCurrent;');
    }
  };
