import test from 'node:test';
import assert from 'node:assert/strict';
import { hundredHandMileNarrative } from '../src/systems/hundredHandMileNarrative.js';
import { hundredHandMile, configureHundredHandMilePorts } from '../src/systems/hundredHandMile.js';
import { voiceArbiter } from '../src/ui/voiceArbiter.js';
import { freshHundredHandMile, HUNDRED_HAND_MILE as C, HUNDRED_HAND_POS as POS, hundredHandContributionId } from '../src/data/hundredHandMile.js';
import { TALLY_THREE } from '../src/data/tallyThree.js';
import { freshTowlineTable, towlineReceiptId, towlineCleanupId } from '../src/data/towlineTable.js';

function fixture() {
  const handlers = new Map(), bus = {
    on(name, fn) { const set = handlers.get(name) || new Set(); handlers.set(name, set); set.add(fn); return () => set.delete(fn); },
    emit(name, p) { for (const fn of handlers.get(name) || []) fn(p); },
  };
  const state = { tick: 1, simTime: 200, playerId: 1, player: {}, world: { currentSectorId: C.sectorId },
    settings: { gameplay: { hundredHandMileCandidate: true } },
    entities: new Map([[1, { alive: true, pos: { ...POS } }]]), towlineTable: freshTowlineTable(),
    salvage: { sources: { [TALLY_THREE.sourceKey]: { extracted: true, extractedBy: 'player', delivery: {
      receiptId: `tally-three:${TALLY_THREE.worldRecordId}`, sourceKey: TALLY_THREE.sourceKey,
      worldRecordId: TALLY_THREE.worldRecordId, stationId: TALLY_THREE.homeStationId,
      manifestId: TALLY_THREE.manifestId, commodityId: 'cmdty_salvage_electronics', qty: 4 } } } } };
  state.towlineTable.members.mara.source.status = 'cleared';
  state.towlineTable.members.mara.source.receipt = { id: towlineReceiptId('mara'), sourceId: towlineCleanupId('mara'), memberId: 'mara', stationId: 'station_ceres', by: 'player', at: 1 };
  const graph = Object.create(hundredHandMile), narrative = Object.create(hundredHandMileNarrative), voice = Object.create(voiceArbiter);
  const world = { live: true, inspectSite: () => ({ ok: world.live, siteId: C.siteId, tick: state.tick }) };
  const owners = { hundredHandMile: graph, hundredHandMileNarrative: narrative, hundredHandMileWorld: world };
  const helpers = {}, ctx = { state, helpers, bus, registry: { get: name => owners[name] } };
  const receipts = new Map(), ports = { inspectSite: () => world.inspectSite(), verifyContributionReceipt: r => JSON.stringify(receipts.get(r.id)) === JSON.stringify(r),
    readConvoy: id => ({ jobId: id, routeId: C.routeId, outcome: 'arrived', witnessedByPlayer: true }) };
  graph.init(ctx); configureHundredHandMilePorts(state, ports); voice.init(ctx); narrative.init(ctx);
  const surfaces = []; bus.on('voice:surface', p => surfaces.push(p));
  function install(module, commodityId = module === 'power' ? 'cmdty_salvage_electronics' : 'cmdty_scrap_metal') {
    const r = { id: hundredHandContributionId(module), siteId: C.siteId, moduleId: module, generation: 0,
      sourceId: module === 'cargo' ? 'player-hold' : `${C.siteId}:${module}-original`, fingerprint: 'verified', at: 1,
      qty: module === 'cargo' ? (commodityId === 'cmdty_food' ? 4 : 2) : 1, by: 'player', commodityId };
    const row = graph.serialize(); row.accepted = true; row.contributions.push(r); row.installedModuleIds.push(module);
    row.completedMilestoneIds.push({ power: 'recover_power', guide: 'restore_guide', cargo: 'deliver_cargo' }[module]);
    graph.deserialize(row); receipts.set(r.id, r);
  }
  function tick(seconds = 0) { state.simTime += seconds; state.tick++; narrative.update(); voice.update(0, state); }
  function arrived() { const row = graph.serialize(); row.finalConvoyJobId = 'budgeted-job'; row.finalConvoyOutcome = 'arrived'; row.completedMilestoneIds.push('witness_convoy'); graph.deserialize(row); }
