    salvage: { sources: {} }, economy: {}, player: { credits: 0, cargo: { items: { cmdty_food: 8, cmdty_scrap_metal: 8 }, usedVolume: 16, usedMass: 16 } } };
  const owners = new Map(), registry = { get: id => owners.get(id) };
  const c = Object.assign({}, cargo, { state, registry }), s = Object.assign({}, salvage, { state, registry });
  const e = Object.assign({}, economy, { state, _registry: registry, bus: { emit() {} } });
  const accepted = new Map();
  let quote = { ok: true, id: hundredHandContributionId(moduleId, 0), siteId: C.siteId, moduleId, generation: 0,
    chapterId: HUNDRED_HAND_CHAPTERS.find(x => x.moduleId === moduleId).id, revision: 0,
    sourceId: 'player-hold', fingerprint: 'native-current-quote', qty: 4, commodityId: 'cmdty_food', by: 'player' };
  if (moduleId !== 'cargo') {
    const d = s.hundredHandSourceDescriptor(moduleId), body = { id: 9, alive: true, occupantGeneration: 7, data: { worldRecordId: d.worldRecordId } };
    state.entities.set(body.id, body); s._sourceRecord(d.sourceKey, true);
    Object.assign(quote, { body, bodyGeneration: 7, sourceKey: d.sourceKey, sourceId: d.worldRecordId, qty: 1, commodityId: Object.keys(d.pool)[0] });
  }
  const graph = { prepareContribution: (_, revision) => revision === undefined || revision === quote.revision ? { ...quote } : { ok: false },
    verifyContributionQuote: q => q.fingerprint === quote.fingerprint && q.body === quote.body,
    contributionReceipt: id => accepted.get(id) || null,
    acceptContribution: (owner, receipt) => { assert.equal(owner, c); assert.deepEqual(c.canonicalHundredHandContribution(receipt.id), receipt); accepted.set(receipt.id, { ...receipt }); return { ok: true }; },
    verifyMilestoneReceipt: () => true };
  owners.set('cargo', c); owners.set('salvage', s); owners.set('economy', e); owners.set('hundredHandMile', graph);
  return { state, c, s, e, graph, quote, accepted };
}

