import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { MeshoptDecoder } from 'meshoptimizer';
import { liveSolidGlbCatalog } from '../src/render/partsLibrary.js';
import { authoredCompoundMeasurement, authoredCompoundCoverage, extractAuthoredConvexSource, isAuthoredNonRenderHelper } from '../scripts/lib/modelTruthAuthoredCompound.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const read = path => JSON.parse(readFileSync(resolve(ROOT, path)));
const sha = path => createHash('sha256').update(readFileSync(resolve(ROOT, path))).digest('hex');
const geometry = read('src/data/hundredHandMileGeometry.json');
const sourceRoot = 'assets/ships/forge/sources/hundred_hand_mile';
const contract = read(`${sourceRoot}/measured-contract.json`);
await MeshoptDecoder.ready;
const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).registerDependencies({'meshopt.decoder': MeshoptDecoder});
const rows = liveSolidGlbCatalog().filter(row => row.family === 'hundred-hand-mile');

function visibleVertices(document) {
  const points = [];
  for (const node of document.getRoot().listNodes()) {
    if (isAuthoredNonRenderHelper(node)) continue;
    const m = node.getWorldMatrix();
    for (const primitive of node.getMesh()?.listPrimitives() || []) {
      const positions = primitive.getAttribute('POSITION');
      for (let i = 0; i < positions.getCount(); i++) {
        const [x,y,z] = positions.getElement(i, []);
        points.push({x:m[0]*x+m[4]*y+m[8]*z+m[12], y:m[1]*x+m[5]*y+m[9]*z+m[13], z:m[2]*x+m[6]*y+m[10]*z+m[14]});
      }
    }
  }
  return points;
}

for (const role of ['mile','power','guide','cargo']) {
  test(`Hundred-Hand ${role}: sealed authored prisms match native source and retain visible coverage`, async () => {
    const g = geometry[role], model = contract.models[role];
    const row = rows.find(r => r.assetId === g.assetId);
    assert(row, 'normal live model catalog contains the asset');
    assert.equal(sha(geometry.sourcePath), geometry.sourceSha256);
    assert.equal(model.geometryRevision, geometry.geometryRevision);
    assert.equal(model.authoringSourceSha256, geometry.sourceSha256);
    assert.deepEqual(model, read(`${sourceRoot}/${model.family}/measured-contract.json`));
    assert.equal(sha(`${sourceRoot}/${model.family}/${model.family}.blend`), model.sourceBlendSha256);
    for (const input of model.sourceInputs) assert.equal(sha(input.path), input.sha256);
    for (const part of g.parts) {
      const component = model.collision.components.find(p => p.node === part.node);
      assert(component, 'every native part has a measured authored helper');
      assert.deepEqual(component.nativeProjection.points, part.points);
      assert.equal(component.nativeProjection.minY, part.minY);
      assert.equal(component.nativeProjection.maxY, part.maxY);
      assert.deepEqual(component.verticesGltf, part.verticesGltf);
      assert.deepEqual(component.triangles, part.triangles);
    }
    for (const [lod,tier] of Object.entries(model.lods)) {
      const path = `${sourceRoot}/${model.family}/${tier.file}`, hash = sha(path);
      assert.equal(hash, tier.sha256);
      const doc = await io.readBinary(readFileSync(resolve(ROOT, path)));
      const binding = {...row, sourceGlbSha256:hash, authoringSourceSha256:geometry.sourceSha256};
      const certificate = extractAuthoredConvexSource(doc, hash, binding);
      const measurement = authoredCompoundMeasurement({...row, sourceGlbSha256:hash});
      assert.equal(authoredCompoundCoverage([], measurement, certificate).sourceCompoundParity, true, `LOD${lod} collision helpers`);
      assert.equal(doc.getRoot().getAsset().extras.conceptGeometry.collisionRepresentation, 'native-y-extruded-xz-prism');
      if (lod === '0') {
        assert.equal(hash, g.sourceGlbSha256);
        const measured = authoredCompoundCoverage(visibleVertices(doc), measurement, certificate);
        assert.equal(measured.overTolerance, false, JSON.stringify(measured));
        assert(measured.coverageWu <= .05, 'all visible source vertices, including lamp feet, stay within strict native coverage');
        const release = await io.readBinary(readFileSync(resolve(ROOT, `assets/ships/release/parts/places/${g.file}`)));
        const released = authoredCompoundCoverage(visibleVertices(release), measurement, certificate);
        assert.equal(released.overTolerance, false, JSON.stringify(released));
        const wrong = structuredClone(certificate); wrong.convexPartsWU[0].maxY += .1;
        assert.throws(() => authoredCompoundCoverage([], measurement, wrong), /disagrees/);
        assert.throws(() => extractAuthoredConvexSource(doc, hash, {...binding, sourceSha:'0'.repeat(64)}), /identity or hash/);
        const node = doc.getRoot().listNodes().find(n => n.getName().startsWith('COLLISION_'));
        const position = node.getMesh().listPrimitives()[0].getAttribute('POSITION');
        const array = position.getArray().slice();
        // Exported GLB has native Y-up accessor coordinates. An intermediate-Y
        // source hull must fail even if its XZ projection still matches.
        array[1] = (Math.min(...Array.from(array).filter((_,i)=>i%3===1)) + Math.max(...Array.from(array).filter((_,i)=>i%3===1))) / 2;
        position.setArray(array);
        assert.throws(() => extractAuthoredConvexSource(doc, hash, binding), /not a native Y prism|not an extruded native polygon/);
      }
    }
  });
}

