import test from 'node:test';
import assert from 'node:assert/strict';
import { createHundredHandMileRouteFixture } from '../scripts/check-hundred-hand-mile-player-route.mjs';
import { fnv1a } from '../src/save/checksum.js';

for (const lane of ['synchronous', 'keyed', 'frozen', 'keyed-after-meta']) {
  test(`one ${lane} save captures original loss before dependent ledgers`, async () => {
    const h = await createHundredHandMileRouteFixture({ startOffset: { x: -45, z: -20 } });
    try {
      h.choose('accept'); h.choose('survey'); h.step(20);
      const save = h.runtime.getSystem('save'), salvage = h.runtime.getSystem('salvage');
      const template = save.serialize('source-loss-boundary');
      const sourceKey = salvage.hundredHandSourceDescriptor('power').sourceKey;
      const original = h.body('power');
      const plan = save._saveCapturePlan();
      const prefix = lane === 'keyed-after-meta' ? { meta: plan[0][1]() } : {};
      // Exercise the physical owner's supported capture fallback, before any death event.
      // Calling the checkpoint/Continue helper first would conceal this ordering bug.
      original.alive = false; original.hull = 0;
      let envelope;
      if (lane === 'synchronous') envelope = save.serialize('source-loss-boundary');
      else {
        let data;
        if (lane === 'frozen') {
          h.s.mode = 'paused';
          assert(save._frozenTickBoundary());
          data = await save._serializeDataFrozenAsync();
          h.s.mode = 'flight';
        } else {
          data = prefix;
          for (const [key, read] of plan.slice(lane === 'keyed-after-meta' ? 1 : 0)) data[key] = read();
        }
        envelope = { ...template, data, checksum: fnv1a(JSON.stringify(data)) };
      }
      envelope = JSON.parse(JSON.stringify(envelope));
      assert(envelope.data.salvage.sources[sourceKey].loss, 'first snapshot contains finite original loss');
      assert.deepEqual(envelope.data.salvage.sources[sourceKey].remainingPool, {});
      assert.equal(envelope.data.salvage.sources[sourceKey].contribution, null);
      assert.equal(envelope.data.hundredHandMileWorld.parts.power.status, 'destroyed');
      assert(envelope.data.hundredHandMile.destroyedModuleIds.includes('power'));
      assert(await h.external(() => save.loadEnvelope(envelope)));
      const physics = h.runtime.getSystem('physics');
      assert(physics._sg02?.world && physics._nativeRestorePending === false && physics._nativeRestoreDeferred === false,
        'save owner finishes native restore without a second reset');
      h.step(3);
      assert.equal(h.body('power'), null);
      assert(salvage.hundredHandSourceLoss('power'));
      assert.equal(h.system._generation('power'), 1);
      h.s.player.cargo.items.cmdty_scrap_metal = 2;
      const result = h.system.contribute('recover_power', h.system.readout().revision);
      assert(result.ok, result.reason);
      assert.equal(result.receipt.generation, 1);
      assert.equal(result.receipt.qty, 2);
      assert.equal(h.s.player.cargo.items.cmdty_scrap_metal || 0, 0);
      h.step(180);
      assert(h.system.readout().installedModuleIds.includes('power'));
      assert.equal(h.body('power').data.hundredHandGeneration, 1);
    } finally { h.dispose(); }
  });
}

